import { randomUUID } from "node:crypto";

const STALE_LEASE_MS = 5 * 60 * 1_000;

export const AGENT_STEERING_STALE_LEASE_MS = STALE_LEASE_MS;

export type AgentSteeringStatus =
  | "pending"
  | "suspended"
  | "in_progress"
  | "delivered"
  | "discarded"
  | "failed";

export type AgentSteeringCompletion = {
  id?: string;
  steeringId?: string;
  requesterSessionKey: string;
  status?: AgentSteeringStatus;
  prompt?: string;
  steeringPrompt?: string;
  result?: unknown;
  steeringResult?: unknown;
  steeringLeaseId?: string | null;
  leaseAcquiredAt?: number | null;
  leaseExpiresAt?: number | null;
  createdAt?: number;
  updatedAt?: number;
  metadata?: Record<string, unknown>;
};

export type AgentSteeringQueueItem = AgentSteeringCompletion & {
  id: string;
  status: AgentSteeringStatus;
};

export type AgentSteeringLease = {
  leaseId: string;
  steeringLeaseId: string;
  item: AgentSteeringQueueItem;
  completion: AgentSteeringQueueItem;
  prompt: string;
  steeringPrompt: string;
  leasedAt: number;
  expiresAt: number;
};

export type AgentSteeringAckResult =
  | { ok: true; acknowledged: true; changed: boolean; item: AgentSteeringQueueItem }
  | { ok: false; acknowledged: false; changed: false; reason: "lease_mismatch" | "not_found" };

export type AgentSteeringReleaseResult =
  | { ok: true; released: boolean; changed: boolean; item: AgentSteeringQueueItem }
  | { ok: false; released: false; changed: boolean; reason: "lease_mismatch" | "not_found" };

export type AgentSteeringLeaseResult =
  | { ok: true; lease: AgentSteeringLease | null; item: AgentSteeringQueueItem | null }
  | { ok: false; lease: null; item: null; reason: "session_mismatch" };

export type AgentSteeringQueueOptions = {
  now?: () => number;
  staleLeaseMs?: number;
  createLeaseId?: () => string;
};

const terminalStatuses = new Set<AgentSteeringStatus>(["delivered", "discarded", "failed"]);

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function stringValue(value: unknown): string | undefined {
  return typeof value === "string" && value.length > 0 ? value : undefined;
}

function resultText(value: unknown): string {
  if (value === undefined || value === null) return "";
  if (typeof value === "string") return value;
  if (typeof value === "number" || typeof value === "boolean" || typeof value === "bigint") {
    return String(value);
  }
  try {
    return JSON.stringify(value);
  } catch {
    return String(value);
  }
}

export function mergeAgentSteeringPrompt(completion: AgentSteeringCompletion): string {
  const prompt = completion.steeringPrompt ?? completion.prompt ?? "";
  const result = completion.steeringResult ?? completion.result;
  const renderedResult = resultText(result);
  if (!renderedResult) return prompt;
  if (!prompt) return renderedResult;
  return `${prompt}\n\n${renderedResult}`;
}

function completionId(completion: AgentSteeringCompletion): string {
  return completion.id ?? completion.steeringId ?? randomUUID();
}

function itemStatus(completion: AgentSteeringCompletion): AgentSteeringStatus {
  return completion.status ?? "pending";
}

function leaseTimestamp(value: unknown): number | undefined {
  if (typeof value === "number" && Number.isFinite(value)) return value;
  if (value instanceof Date) return value.getTime();
  if (typeof value === "string") {
    const parsed = Date.parse(value);
    return Number.isFinite(parsed) ? parsed : undefined;
  }
  return undefined;
}

function leaseAge(item: AgentSteeringQueueItem, now: number): number {
  const acquired = leaseTimestamp(item.leaseAcquiredAt);
  if (acquired !== undefined) return now - acquired;
  const updated = leaseTimestamp(item.updatedAt);
  return updated === undefined ? 0 : now - updated;
}

function terminal(value: unknown): boolean {
  return typeof value === "string" && terminalStatuses.has(value as AgentSteeringStatus);
}

export class AgentSteeringQueue {
  private readonly items = new Map<string, AgentSteeringQueueItem>();
  private readonly now: () => number;
  private readonly staleLeaseMs: number;
  private readonly createLeaseId: () => string;

  constructor(options: AgentSteeringQueueOptions = {}) {
    this.now = options.now ?? Date.now;
    this.staleLeaseMs = options.staleLeaseMs ?? STALE_LEASE_MS;
    this.createLeaseId = options.createLeaseId ?? (() => randomUUID());
  }

  enqueue(completion: AgentSteeringCompletion): AgentSteeringQueueItem {
    const id = completionId(completion);
    const timestamp = this.now();
    const existing = this.items.get(id);
    const item: AgentSteeringQueueItem = {
      ...completion,
      id,
      status: itemStatus(completion),
      steeringLeaseId: completion.steeringLeaseId ?? existing?.steeringLeaseId ?? null,
      leaseAcquiredAt: completion.leaseAcquiredAt ?? existing?.leaseAcquiredAt ?? null,
      leaseExpiresAt: completion.leaseExpiresAt ?? existing?.leaseExpiresAt ?? null,
      createdAt: completion.createdAt ?? existing?.createdAt ?? timestamp,
      updatedAt: timestamp,
    };
    this.items.set(id, item);
    return { ...item };
  }

  add(completion: AgentSteeringCompletion): AgentSteeringQueueItem {
    return this.enqueue(completion);
  }

  complete(completion: AgentSteeringCompletion): AgentSteeringQueueItem {
    return this.enqueue({ ...completion, status: "pending" });
  }

  cancel(id: string, status: "discarded" | "failed" = "discarded"): boolean {
    const item = this.items.get(id);
    if (!item || terminal(item.status)) return false;
    item.status = status;
    item.steeringLeaseId = null;
    item.leaseAcquiredAt = null;
    item.leaseExpiresAt = null;
    item.updatedAt = this.now();
    return true;
  }

  discard(id: string): boolean {
    return this.cancel(id, "discarded");
  }

  fail(id: string): boolean {
    return this.cancel(id, "failed");
  }

  pending(requesterSessionKey: string): AgentSteeringQueueItem[] {
    return [...this.items.values()]
      .filter(
        (item) =>
          item.requesterSessionKey === requesterSessionKey &&
          (item.status === "pending" || item.status === "suspended") &&
          !terminal(item.status),
      )
      .map((item) => ({ ...item }));
  }

  listPending(requesterSessionKey: string): AgentSteeringQueueItem[] {
    return this.pending(requesterSessionKey);
  }

  lease(requesterSessionKey: string): AgentSteeringLeaseResult {
    const timestamp = this.now();
    const candidates = [...this.items.values()]
      .filter((item) => item.requesterSessionKey === requesterSessionKey)
      .filter((item) => item.status === "pending" || item.status === "suspended")
      .sort((left, right) => {
        const byCreation = (left.createdAt ?? 0) - (right.createdAt ?? 0);
        return byCreation === 0 ? left.id.localeCompare(right.id) : byCreation;
      });

    for (const item of candidates) {
      item.status = "in_progress";
      item.steeringLeaseId = this.createLeaseId();
      item.leaseAcquiredAt = timestamp;
      item.leaseExpiresAt = timestamp + this.staleLeaseMs;
      item.updatedAt = timestamp;
      const lease = this.toLease(item);
      return { ok: true, lease, item: { ...item } };
    }
    return { ok: true, lease: null, item: null };
  }

  leaseForSession(requesterSessionKey: string): AgentSteeringLease | null {
    return this.lease(requesterSessionKey).lease;
  }

  leaseSteering(requesterSessionKey: string): AgentSteeringLease | null {
    return this.leaseForSession(requesterSessionKey);
  }

  leasePending(requesterSessionKey: string): AgentSteeringLease | null {
    return this.leaseForSession(requesterSessionKey);
  }

  reclaimStale(requesterSessionKey: string): AgentSteeringLeaseResult {
    const timestamp = this.now();
    for (const item of this.items.values()) {
      if (
        item.requesterSessionKey === requesterSessionKey &&
        item.status === "in_progress" &&
        leaseAge(item, timestamp) > this.staleLeaseMs
      ) {
        item.status = "pending";
        item.steeringLeaseId = null;
        item.leaseAcquiredAt = null;
        item.leaseExpiresAt = null;
        item.updatedAt = timestamp;
      }
    }
    return this.lease(requesterSessionKey);
  }

  ack(id: string, leaseId: string): AgentSteeringAckResult {
    const item = this.items.get(id);
    if (!item) return { ok: false, acknowledged: false, changed: false, reason: "not_found" };
    if (item.status !== "in_progress" || item.steeringLeaseId !== leaseId) {
      return { ok: false, acknowledged: false, changed: false, reason: "lease_mismatch" };
    }
    item.status = "delivered";
    item.steeringLeaseId = null;
    item.leaseAcquiredAt = null;
    item.leaseExpiresAt = null;
    item.updatedAt = this.now();
    return { ok: true, acknowledged: true, changed: true, item: { ...item } };
  }

  acknowledge(id: string, leaseId: string): AgentSteeringAckResult {
    return this.ack(id, leaseId);
  }

  ackLease(lease: AgentSteeringLease | { item?: AgentSteeringQueueItem; completion?: AgentSteeringQueueItem; leaseId?: string; steeringLeaseId?: string }, leaseId?: string): AgentSteeringAckResult {
    const item = lease.item ?? lease.completion;
    const id = item?.id ?? item?.steeringId ?? "";
    const effectiveLeaseId = leaseId ?? lease.steeringLeaseId ?? lease.leaseId ?? item?.steeringLeaseId ?? "";
    return this.ack(id, effectiveLeaseId);
  }

  release(id: string, leaseId: string): AgentSteeringReleaseResult {
    const item = this.items.get(id);
    if (!item) return { ok: false, released: false, changed: false, reason: "not_found" };
    if (item.status !== "in_progress" || item.steeringLeaseId !== leaseId) {
      return { ok: false, released: false, changed: false, reason: "lease_mismatch" };
    }
    item.status = "pending";
    item.steeringLeaseId = null;
    item.leaseAcquiredAt = null;
    item.leaseExpiresAt = null;
    item.updatedAt = this.now();
    return { ok: true, released: true, changed: true, item: { ...item } };
  }

  releaseLease(lease: AgentSteeringLease | { item?: AgentSteeringQueueItem; completion?: AgentSteeringQueueItem; leaseId?: string; steeringLeaseId?: string }, leaseId?: string): AgentSteeringReleaseResult {
    const item = lease.item ?? lease.completion;
    const id = item?.id ?? item?.steeringId ?? "";
    const effectiveLeaseId = leaseId ?? lease.steeringLeaseId ?? lease.leaseId ?? item?.steeringLeaseId ?? "";
    return this.release(id, effectiveLeaseId);
  }

  get(id: string): AgentSteeringQueueItem | undefined {
    const item = this.items.get(id);
    return item ? { ...item } : undefined;
  }

  size(): number {
    return this.items.size;
  }

  clear(): void {
    this.items.clear();
  }

  private toLease(item: AgentSteeringQueueItem): AgentSteeringLease {
    const prompt = mergeAgentSteeringPrompt(item);
    return {
      leaseId: item.steeringLeaseId ?? "",
      steeringLeaseId: item.steeringLeaseId ?? "",
      item: { ...item },
      completion: { ...item },
      prompt,
      steeringPrompt: prompt,
      leasedAt: item.leaseAcquiredAt ?? this.now(),
      expiresAt: item.leaseExpiresAt ?? this.now() + this.staleLeaseMs,
    };
  }
}

export function createAgentSteeringQueue(options?: AgentSteeringQueueOptions): AgentSteeringQueue {
  return new AgentSteeringQueue(options);
}

export function enqueueAgentSteering(queue: AgentSteeringQueue, completion: AgentSteeringCompletion): AgentSteeringQueueItem {
  return queue.enqueue(completion);
}

export function leaseAgentSteering(queue: AgentSteeringQueue, requesterSessionKey: string): AgentSteeringLease | null {
  return queue.leaseForSession(requesterSessionKey);
}

export function ackAgentSteering(queue: AgentSteeringQueue, id: string, leaseId: string): AgentSteeringAckResult {
  return queue.ack(id, leaseId);
}

export function releaseAgentSteering(queue: AgentSteeringQueue, id: string, leaseId: string): AgentSteeringReleaseResult {
  return queue.release(id, leaseId);
}

export function mergeSteeringPrompt(completion: AgentSteeringCompletion): string {
  return mergeAgentSteeringPrompt(completion);
}

export function isTerminalSteeringStatus(status: unknown): boolean {
  return terminal(status);
}

export default AgentSteeringQueue;

