    const effectiveLeaseId = leaseId ?? lease.steeringLeaseId ?? lease.leaseId ?? item?.steeringLeaseId ?? "";
    return this.ack(id, effectiveLeaseId);
  }

  release(id: string, leaseId: string): AgentSteeringReleaseResult {
    const item = this.items.get(id);
    if (!item) return { ok: false, released: false, changed: false, reason: "not_found" };
    if (item.status !== "in_progress" || item.steeringLeaseId !== leaseId) {
      return { ok: false, released: false, changed: false, reason: "lease_mismatch" };
    }
    item.status = "pending";
    item.steeringLeaseId = null;
    item.leaseAcquiredAt = null;
    item.leaseExpiresAt = null;
    item.updatedAt = this.now();
    return { ok: true, released: true, changed: true, item: { ...item } };
  }

  releaseLease(lease: AgentSteeringLease | { item?: AgentSteeringQueueItem; completion?: AgentSteeringQueueItem; leaseId?: string; steeringLeaseId?: string }, leaseId?: string): AgentSteeringReleaseResult {
    const item = lease.item ?? lease.completion;
    const id = item?.id ?? item?.steeringId ?? "";
    const effectiveLeaseId = leaseId ?? lease.steeringLeaseId ?? lease.leaseId ?? item?.steeringLeaseId ?? "";
    return this.release(id, effectiveLeaseId);
  }

  get(id: string): AgentSteeringQueueItem | undefined {
    const item = this.items.get(id);
    return item ? { ...item } : undefined;
  }

  size(): number {
    return this.items.size;
  }

  clear(): void {
    this.items.clear();
  }

  private toLease(item: AgentSteeringQueueItem): AgentSteeringLease {
    const prompt = mergeAgentSteeringPrompt(item);
    return {
      leaseId: item.steeringLeaseId ?? "",
      steeringLeaseId: item.steeringLeaseId ?? "",
      item: { ...item },
      completion: { ...item },
      prompt,
      steeringPrompt: prompt,
      leasedAt: item.leaseAcquiredAt ?? this.now(),
      expiresAt: item.leaseExpiresAt ?? this.now() + this.staleLeaseMs,
    };
  }
}

export function createAgentSteeringQueue(options?: AgentSteeringQueueOptions): AgentSteeringQueue {
  return new AgentSteeringQueue(options);
}

export function enqueueAgentSteering(queue: AgentSteeringQueue, completion: AgentSteeringCompletion): AgentSteeringQueueItem {
  return queue.enqueue(completion);
}

export function leaseAgentSteering(queue: AgentSteeringQueue, requesterSessionKey: string): AgentSteeringLease | null {
  return queue.leaseForSession(requesterSessionKey);
}

export function ackAgentSteering(queue: AgentSteeringQueue, id: string, leaseId: string): AgentSteeringAckResult {
  return queue.ack(id, leaseId);
}

export function releaseAgentSteering(queue: AgentSteeringQueue, id: string, leaseId: string): AgentSteeringReleaseResult {
  return queue.release(id, leaseId);
}

export function mergeSteeringPrompt(completion: AgentSteeringCompletion): string {
  return mergeAgentSteeringPrompt(completion);
}

export function isTerminalSteeringStatus(status: unknown): boolean {
  return terminal(status);
}

export default AgentSteeringQueue;
